{
  "passageId": "sf-film-society",
  "items": [
    {
      "id": "R1",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "장르 영화는 영화가 대중의 취향에 반응한다는 일반적 설명을 보여 주는 대표 사례이므로 구체화·예시에 해당한다."
    },
    {
      "id": "R2",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "장르의 성쇠와 관습의 변화는 장르 영화에 대중의 취향이 반영되는 구체적인 양상이다."
    },
    {
      "id": "R3",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "영화가 반영하는 대상에 관한 논의를 대중의 취향에서 공유된 이념까지 확장한다."
    },
    {
      "id": "R4",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "동일한 매체인 영화가 이념을 드러내면서 동시에 숨긴다는 양면성을 제시한다."
    },
    {
      "id": "R5",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "영화가 이념을 숨긴다는 설명을 어떤 성격의 이념이 감추어지는지 밝혀 구체화한다."
    },
    {
      "id": "R6",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "이념이 투명하게 드러나지 않는 한계에 대응하여 표면의 모티브와 이미지를 해석하는 방법을 제시한다."
    },
    {
      "id": "R7",
      "type": "PROCESS",
      "otherName": "",
      "reason": "이미지를 해석해 읽어 낸 이념을 바탕으로 사회를 이해하는 다음 단계가 이어지므로 처리 단계의 연결에 해당한다."
    },
    {
      "id": "R8",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "영화 이미지를 해석해 사회를 이해한다는 방법을 1920년대 독일 영화라는 구체적인 대상에 적용한다."
    },
    {
      "id": "R9",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "앞서 설명한 크라카우어의 해석 방법을 모티브와 이미지를 통한 사회의 심층적 이해로 요약하여 재진술한다."
    },
    {
      "id": "R10",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "영화를 통해 사회를 이해하는 방식에 관해 크라카우어와 제임슨의 서로 다른 관점을 공격 없이 나란히 제시한다."
    },
    {
      "id": "R11",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "현대 사회의 분산성과 파편성을 근거로 그 총체적 양상은 역사가 된 이후에야 파악된다고 설명한다."
    },
    {
      "id": "R12",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "현재를 역사처럼 조망하여 사회의 총체성을 파악하기 위한 수단으로 서사를 통한 역사화를 제시한다."
    },
    {
      "id": "R13",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "사건을 완료된 과거처럼 서술한다는 서사의 특성이 총체적인 조망을 가능하게 한다는 설명의 근거가 된다."
    },
    {
      "id": "R14",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "서사가 역사화를 통해 총체적 조망을 가능하게 한다는 원리를 미래를 다루는 SF에도 적용한다."
    },
    {
      "id": "R15",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "서사의 역사화가 적용되는 대상으로 SF를 언급한 뒤 SF 자체의 정의와 성립 기준으로 논의를 옮긴다."
    },
    {
      "id": "R16",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "SF가 과학적 지식에 기반한다는 사실을 인정하면서도 모든 소재와 서사의 사실성까지 요구되는 것은 아니라는 한계를 밝힌다."
    },
    {
      "id": "R17",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "SF의 중요한 기준이 과학적 진위가 아니라 개연성이라는 점은 모든 소재와 서사가 과학적 사실일 필요는 없다는 판단을 뒷받침한다."
    },
    {
      "id": "R18",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "개연성의 뜻을 주요 설정과 사건의 인과 관계에 대한 합리적 납득 가능성으로 풀이한다."
    },
    {
      "id": "R19",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "SF의 경이로움이라는 장르적 특징을 장대하고 압도적인 대상이 주는 경험으로 구체화한다."
    },
    {
      "id": "R20",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "경이로움이 SF의 특징이라는 설명을 그 경이로움을 유발하는 대상과 노붐 개념을 제시하여 자세히 푼다."
    },
    {
      "id": "R21",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "노붐의 기능을 설명하면서 일회적인 놀라움과 작품 전반에 미치는 영향이라는 서로 다른 작용 범위를 대비한다."
    },
    {
      "id": "R22",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "작품 전반을 지배한다는 노붐의 기능이 노붐을 진정한 주인공이라고 평가하는 근거가 된다."
    },
    {
      "id": "R23",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "현실과 허구 세계의 차이를 드러내는 핵심 요소라는 점이 노붐의 주인공적 위상을 뒷받침한다."
    },
    {
      "id": "R24",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "작품의 세계관을 드러낸다는 노붐의 기능을 근거로 노붐을 SF의 진정한 주인공이라고 평가한다."
    },
    {
      "id": "R25",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "SF가 미래 세계를 상상하지만 그 상상의 기반은 작품이 생산된 시대라는 동일 대상의 양면성을 제시한다."
    },
    {
      "id": "R26",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "미래에 대한 상상이 작품 생산 시대에 기반한다는 사실이 SF를 현실의 반영으로 보는 판단의 근거이다."
    },
    {
      "id": "R27",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "SF의 미래 상상이 당대 현실에 기반한다는 설명으로부터 그 인물과 설정이 현실과 유사하면서도 다르다는 설명을 도출한다."
    },
    {
      "id": "R28",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "동일한 SF의 인물과 설정이 현실을 닮으면서도 현실과 다르다는 양면성을 제시한다."
    },
    {
      "id": "R29",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "인지적 낯섦을 촉발한다는 설명을 친숙했던 현실의 대상이 낯설고 새롭게 느껴지는 경험으로 구체화한다."
    },
    {
      "id": "R30",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "현실과 닮으면서 다른 SF 세계가 낯섦을 촉발한다는 설명에서 특히 다름이 유발 요인임을 밝혀 구체화한다."
    },
    {
      "id": "R31",
      "type": "OTHER",
      "otherName": "병렬적 효과",
      "reason": "두 문장은 다름을 인지한 결과인 거리 두기와 비판적 바라보기를 병렬로 제시하며 둘 사이의 인과나 순서를 별도로 확정하지 않는다."
    },
    {
      "id": "R32",
      "type": "CAUSE",
      "otherName": "",
      "reason": "현실을 낯설게 느끼는 경험이 현실에 대한 거리 두기와 비판적 성찰을 일으키는 작용으로 이어진다."
    },
    {
      "id": "R33",
      "type": "OTHER",
      "otherName": "공통 초점",
      "reason": "노붐의 기능과 낯섦의 원인에 관한 두 설명은 현실과 허구의 차이에 공통으로 주목하지만 서로의 인과나 근거 관계를 직접 제시하지 않는다."
    },
    {
      "id": "R34",
      "type": "VIEW_AGREEMENT",
      "otherName": "",
      "reason": "크라카우어와 수빈은 예술 작품이 그것이 생산된 사회와 현실을 반영한다는 관점을 공유한다."
    },
    {
      "id": "R35",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "미지의 세계에 대한 동경을 충족하는 허구적 이야기 가운데 유토피아에 대한 동경을 다룬 이야기에 초점을 맞추어 구체화한다."
    },
    {
      "id": "R36",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "유토피아 이야기와 SF의 유사성은 수빈이 유토피아를 SF의 중요한 소재로 받아들이는 근거가 된다."
    },
    {
      "id": "R37",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "환경 오염과 전쟁으로 인한 인류의 위기를 근거로 이상적 세계를 탐색하는 SF의 역할이 더욱 중요하다는 평가를 뒷받침한다."
    },
    {
      "id": "R38",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "유토피아를 SF의 소재로 인정하는 논의에서 나아가 이상적 세계를 탐색하는 SF의 현대적 역할과 중요성으로 논의를 확장한다."
    }
  ]
}

